31	type ActionResult<T = void> =
32	  | { ok: true; data: T }
33	  | { ok: false; error: string }
34	
35	type MutationRole = 'owner' | 'admin' | 'artist'
36	type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
37	
38	function canWrite(role: ReadRole): role is MutationRole {
39	  return role === 'owner' || role === 'admin' || role === 'artist'
40	}
41	
42	function canAdmin(role: ReadRole): boolean {
43	  return role === 'owner' || role === 'admin'
44	}
