46	// ─── Create ────────────────────────────────────────────────────────────────────
47	
48	export async function createProjectAction(
49	  formData: FormData
50	): Promise<ActionResult<{ id: string }>> {
51	  const auth = await getAuthenticatedUser()
52	  if (!auth) return { ok: false, error: 'Not authenticated' }
53	
54	  const role = auth.role as ReadRole
55	  // Receptionist can create projects per RLS
56	  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }
57	
58	  const raw = {
59	    clientId: formData.get('clientId'),
60	    name: formData.get('name'),
61	    description: formData.get('description') || undefined,
62	    placement: formData.get('placement') || undefined,
63	    style: formData.get('style') || undefined,
64	    primaryArtistId: formData.get('primaryArtistId') || undefined,
65	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
66	      ? Number(formData.get('totalSessionsPlanned'))
67	      : undefined,
68	    totalPriceCents: formData.get('totalPriceCents')
69	      ? Number(formData.get('totalPriceCents'))
70	      : 0,
71	    moodboardUrl: formData.get('moodboardUrl') || undefined,
72	    initialDepositCents: formData.get('initialDepositCents')
73	      ? Number(formData.get('initialDepositCents'))
74	      : undefined,
75	  }
76	
77	  const parsed = projectCreateSchema.safeParse(raw)
78	  if (!parsed.success) {
79	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
80	  }
81	
82	  // requestDeposit and bookingId are wizard-level flags not in the schema
83	  const requestDeposit = formData.get('requestDeposit') === 'true'
84	  const bookingIdRaw = formData.get('bookingId')
85	  const bookingId = typeof bookingIdRaw === 'string' && bookingIdRaw.length > 0
86	    ? bookingIdRaw
87	    : null
88	
89	  try {
90	    const project = await createProject(auth.studioId, parsed.data)
91	    revalidatePath('/projects')
92	
93	    // requestDeposit wiring — fire deposit reminder when a booking was created in same wizard flow
94	    if (requestDeposit) {
95	      if (bookingId) {
96	        const { sendDepositReminderAction } = await import('@/app/(app)/inbox/actions')
97	        const reminderResult = await sendDepositReminderAction(bookingId)
98	        if (!reminderResult.ok) {
99	          // Non-fatal — project created; log and continue
100	          logger.warn(
101	            { bookingId, projectId: project.id, error: reminderResult.error },
102	            'createProjectAction: deposit reminder send failed (non-fatal)',
103	          )
104	        } else {
105	          logger.info(
106	            { bookingId, projectId: project.id },
107	            'createProjectAction: deposit reminder sent',
108	          )
109	        }
110	      } else {
111	        // No booking yet — reminder deferred to first session booking
112	        logger.info(
113	          { projectId: project.id },
114	          'createProjectAction: requestDeposit=true but no bookingId — reminder deferred to first session booking',
115	        )
116	      }
117	    }
118	
119	    return { ok: true, data: { id: project.id } }
120	  } catch (err) {
121	    logger.error({ err }, 'createProjectAction failed')
122	    return { ok: false, error: 'Failed to create project' }
123	  }
124	}
