128	export async function updateProjectAction(
129	  id: string,
130	  formData: FormData
131	): Promise<ActionResult<void>> {
132	  const auth = await getAuthenticatedUser()
133	  if (!auth) return { ok: false, error: 'Not authenticated' }
134	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
135	
136	  const raw = {
137	    name: formData.get('name') || undefined,
138	    description: formData.get('description') ?? undefined,
139	    placement: formData.get('placement') ?? undefined,
140	    style: formData.get('style') ?? undefined,
141	    primaryArtistId: formData.get('primaryArtistId') ?? undefined,
142	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
143	      ? Number(formData.get('totalSessionsPlanned'))
144	      : undefined,
145	    totalPriceCents: formData.get('totalPriceCents')
146	      ? Number(formData.get('totalPriceCents'))
147	      : undefined,
148	    moodboardUrl: formData.get('moodboardUrl') ?? undefined,
149	    status: formData.get('status') ?? undefined,
150	  }
151	
152	  const parsed = projectUpdateSchema.safeParse(raw)
153	  if (!parsed.success) {
154	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
155	  }
156	
157	  try {
158	    await updateProject(auth.studioId, id, parsed.data)
159	    revalidatePath('/projects')
160	    revalidatePath(`/projects/${id}`)
161	    return { ok: true, data: undefined }
162	  } catch (err) {
