248	export async function addReferenceAction(
249	  projectId: string,
250	  formData: FormData
251	): Promise<ActionResult<{ id: string }>> {
252	  const auth = await getAuthenticatedUser()
253	  if (!auth) return { ok: false, error: 'Not authenticated' }
254	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
