257	
258	  const file = formData.get('file') as File | null
259	  if (!file) return { ok: false, error: 'No file provided' }
260	
261	  // Upload to Supabase Storage
262	  const fileExt = file.name.split('.').pop() ?? 'jpg'
263	  const storagePath = `${auth.studioId}/${projectId}/refs/${Date.now()}.${fileExt}`
264	
265	  const { error: uploadError } = await supabase.storage
266	    .from('project-references')
267	    .upload(storagePath, file, { upsert: false })
