269	  if (uploadError) {
270	    logger.error({ uploadError, projectId }, 'addReferenceAction upload failed')
271	    return { ok: false, error: 'Failed to upload image' }
272	  }
273	
274	  const raw = {
275	    storagePath,
276	    caption: (formData.get('caption') as string) || undefined,
277	    displayOrder: formData.get('displayOrder')
278	      ? Number(formData.get('displayOrder'))
279	      : undefined,
280	  }
281	
282	  const parsed = addReferenceSchema.safeParse(raw)
283	  if (!parsed.success) {
284	    return { ok: false, error: 'Validation failed' }
285	  }
286	
287	  try {
288	    const ref = await addProjectReference(auth.studioId, projectId, parsed.data)
289	    revalidatePath(`/projects/${projectId}`)
