449	// ─── Status change + activity log ─────────────────────────────────────────────
450	
451	export async function updateProjectStatusAction(
452	  projectId: string,
453	  newStatus: ProjectStatus
454	): Promise<ActionResult<void>> {
455	  const auth = await getAuthenticatedUser()
456	  if (!auth) return { ok: false, error: 'Not authenticated' }
457	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
458	
459	  const supabase = await createClient()
460	
461	  const { data: current, error: fetchErr } = await supabase
462	    .from('projects')
463	    .select('status')
464	    .eq('id', projectId)
465	    .eq('studio_id', auth.studioId)
466	    .single()
467	
468	  if (fetchErr || !current) {
469	    return { ok: false, error: 'Project not found' }
470	  }
471	
472	  const prevStatus = current.status
473	
474	  const { error: updateErr } = await supabase
475	    .from('projects')
476	    .update({ status: newStatus, updated_at: new Date().toISOString() })
477	    .eq('id', projectId)
478	    .eq('studio_id', auth.studioId)
479	
480	  if (updateErr) {
481	    logger.error({ updateErr, projectId }, 'updateProjectStatusAction update failed')
482	    return { ok: false, error: 'Failed to update status' }
483	  }
484	
485	  // Append activity log — best-effort
486	  await supabase
487	    .from('project_activity_log' as 'projects')
488	    .insert({
489	      project_id: projectId,
490	      actor_id: auth.user.id,
491	      event_type: 'status_changed',
492	      details: { prev_status: prevStatus, new_status: newStatus },
493	    } as never)
494	    .then(({ error: logErr }) => {
495	      if (logErr) logger.warn({ logErr, projectId }, 'activity log insert failed')
496	    })
497	
498	  revalidatePath('/projects')
499	  revalidatePath(`/projects/${projectId}`)
500	  return { ok: true, data: undefined }
501	}
