584	export async function applyDepositToSessionAction(
585	  projectId: string,
586	  bookingId: string,
587	  amountCents: number
588	): Promise<ActionResult<void>> {
589	  const auth = await getAuthenticatedUser()
590	  if (!auth) return { ok: false, error: 'Not authenticated' }
591	  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can apply deposits' }
592	
593	  if (amountCents <= 0) return { ok: false, error: 'Amount must be positive' }
594	
595	  const supabase = await createClient()
596	
597	  const { error } = await _insertDepositTransaction(supabase, {
598	    project_id: projectId,
599	    type: 'applied',
600	    amount_cents: amountCents,
601	    applied_to_session_id: bookingId,
602	    created_by: auth.user.id,
603	  })
604	
