// ─── Rate-limit helper (W2) ───────────────────────────────────

/**
 * Returns the authenticated user's ID for use as a rate-limit key,
 * or null when the session is missing (caller should bail out early).
 */
async function getAuthUserId(): Promise<string | null> {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  return user?.id ?? null
}

async function checkSendRatelimit(
  userId: string,
  actionName: string,
): Promise<{ blocked: true; error: string } | { blocked: false }> {
  const { success } = await authedRatelimit.limit(`${userId}:${actionName}`)
  if (!success) {
    logger.warn({ userId, action: actionName }, 'inbox: rate limit exceeded')
    return { blocked: true, error: 'Too many requests. Please wait a minute before sending again.' }
  }
  return { blocked: false }
}

